import { computed, ref } from 'vue'

export const supportedLocales = [
  { code: 'en-US', label: 'English (US)' },
  { code: 'es-ES', label: 'Español (España)' },
  { code: 'de', label: 'Deutsch' },
  { code: 'hi', label: 'हिन्दी' },
  { code: 'pt', label: 'Português' },
  { code: 'fr', label: 'Français' },
  { code: 'zh-Hans', label: '简体中文' },
  { code: 'ru', label: 'Русский' },
] as const

export type Locale = typeof supportedLocales[number]['code']
type MessageCatalog = Record<string, string>

const localeStorageKey = 'opencode-mobile.locale'
const fallbackLocale: Locale = 'en-US'

function detectedLocale(): Locale {
  const saved = localStorage.getItem(localeStorageKey)
  if (supportedLocales.some(({ code }) => code === saved)) return saved as Locale
  const language = navigator.language.toLowerCase()
  if (language.startsWith('es')) return 'es-ES'
  if (language.startsWith('de')) return 'de'
  if (language.startsWith('hi')) return 'hi'
  if (language.startsWith('pt')) return 'pt'
  if (language.startsWith('fr')) return 'fr'
  if (language.startsWith('zh')) return 'zh-Hans'
  if (language.startsWith('ru')) return 'ru'
  return fallbackLocale
}

const currentLocale = ref<Locale>(detectedLocale())

