const catalogs: Record<Locale, MessageCatalog> = {
  'en-US': en, 'es-ES': es, de, hi, pt, fr, 'zh-Hans': zh, ru,
}

export function t(key: string, values: Record<string, string | number> = {}): string {
  const message = catalogs[currentLocale.value][key] ?? en[key] ?? key
  return message.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`))
}

export function setLocale(locale: Locale): void {
  currentLocale.value = locale
  localStorage.setItem(localeStorageKey, locale)
  document.documentElement.lang = locale
}

export function useI18n() {
  return { locale: currentLocale, t, setLocale, supportedLocales, localeLabel: computed(() => supportedLocales.find(({ code }) => code === currentLocale.value)?.label ?? 'English (US)') }
}

export const i18n = { install(app: { config: { globalProperties: Record<string, unknown> } }) { app.config.globalProperties.$t = t } }
